-- 月末人员规模与变动
-- 题目资源4.2.1，原生MySQL8.4尚未验证

WITH m AS (SELECT month_key,MAX(day) last_day FROM calendar_days WHERE month_key BETWEEN '2024-12' AND '2025-12' GROUP BY month_key), a AS (SELECT d.department_id,m.month_key,COUNT(h.employee_id) headcount FROM departments d CROSS JOIN m LEFT JOIN employment_history h ON h.department_id=d.department_id AND h.start_date<=m.last_day AND (h.end_date IS NULL OR h.end_date>m.last_day) GROUP BY d.department_id,m.month_key), b AS (SELECT *,LAG(headcount) OVER(PARTITION BY department_id ORDER BY month_key) prev FROM a) SELECT department_id,month_key,headcount,headcount-prev net_change FROM b WHERE month_key BETWEEN '2025-01' AND '2025-12' ORDER BY department_id,month_key;

WITH m AS (SELECT month_key,MAX(day) last_day FROM calendar_days WHERE (month_key>='2024-12' AND month_key<='2025-12') GROUP BY month_key), a AS (SELECT d.department_id,m.month_key,COUNT(h.employee_id) headcount FROM departments d CROSS JOIN m LEFT JOIN employment_history h ON h.department_id=d.department_id AND h.start_date<=m.last_day AND (h.end_date IS NULL OR h.end_date>m.last_day) GROUP BY d.department_id,m.month_key), b AS (SELECT *,LAG(headcount) OVER(PARTITION BY department_id ORDER BY month_key) prev FROM a) SELECT department_id,month_key,headcount,headcount-prev net_change FROM b WHERE (month_key>='2025-01' AND month_key<='2025-12') ORDER BY department_id,month_key;
